CREATE TABLE tenants (id text PRIMARY KEY, name text NOT NULL, demo boolean NOT NULL DEFAULT false, currency text NOT NULL DEFAULT 'LKR', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users (id text PRIMARY KEY, tenant_id text NOT NULL REFERENCES tenants(id), email text NOT NULL UNIQUE, name text NOT NULL, password_hash text NOT NULL, role text NOT NULL CHECK(role IN ('ADMIN','PLANNER','WAREHOUSE','OPERATOR','QUALITY','SALES','VIEWER')), active boolean NOT NULL DEFAULT true);
CREATE TABLE factories (id text PRIMARY KEY, tenant_id text NOT NULL REFERENCES tenants(id), name text NOT NULL, location text NOT NULL, UNIQUE(tenant_id,id));
CREATE TABLE warehouses (id text PRIMARY KEY, tenant_id text NOT NULL REFERENCES tenants(id), factory_id text NOT NULL, name text NOT NULL, kind text NOT NULL, UNIQUE(tenant_id,id), FOREIGN KEY(tenant_id,factory_id) REFERENCES factories(tenant_id,id));
CREATE TABLE items (id text PRIMARY KEY, tenant_id text NOT NULL REFERENCES tenants(id), sku text NOT NULL, name text NOT NULL, type text NOT NULL CHECK(type IN ('RAW_MATERIAL','FINISHED_GOOD','PACKAGING')), uom text NOT NULL CHECK(uom IN ('kg','pcs')), standard_cost numeric(20,6) NOT NULL CHECK(standard_cost>=0), reorder_level numeric(20,6) NOT NULL DEFAULT 0 CHECK(reorder_level>=0), active boolean NOT NULL DEFAULT true, UNIQUE(tenant_id,id), UNIQUE(tenant_id,sku));
CREATE TABLE partners (id text PRIMARY KEY, tenant_id text NOT NULL REFERENCES tenants(id), name text NOT NULL, type text NOT NULL CHECK(type IN ('SUPPLIER','CUSTOMER')), email text, payment_days integer NOT NULL DEFAULT 30, UNIQUE(tenant_id,id));
CREATE TABLE machines (id text PRIMARY KEY, tenant_id text NOT NULL REFERENCES tenants(id), factory_id text NOT NULL, code text NOT NULL, name text NOT NULL, kind text NOT NULL, status text NOT NULL CHECK(status IN ('RUNNING','IDLE','MAINTENANCE')), hourly_rate numeric(20,6) NOT NULL CHECK(hourly_rate>=0), UNIQUE(tenant_id,id), FOREIGN KEY(tenant_id,factory_id) REFERENCES factories(tenant_id,id));
CREATE TABLE boms (id text PRIMARY KEY, tenant_id text NOT NULL REFERENCES tenants(id), product_id text NOT NULL, revision text NOT NULL, status text NOT NULL CHECK(status IN ('DRAFT','APPROVED')), output_qty numeric(20,6) NOT NULL CHECK(output_qty>0), yield_factor numeric(10,6) NOT NULL DEFAULT 1 CHECK(yield_factor>0 AND yield_factor<=1), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,id), UNIQUE(tenant_id,product_id,revision), FOREIGN KEY(tenant_id,product_id) REFERENCES items(tenant_id,id));
CREATE TABLE bom_lines (id text PRIMARY KEY, tenant_id text NOT NULL REFERENCES tenants(id), bom_id text NOT NULL, item_id text NOT NULL, quantity numeric(20,6) NOT NULL CHECK(quantity>0), UNIQUE(tenant_id,bom_id,item_id), FOREIGN KEY(tenant_id,bom_id) REFERENCES boms(tenant_id,id), FOREIGN KEY(tenant_id,item_id) REFERENCES items(tenant_id,id));
CREATE TABLE sales_orders (id text PRIMARY KEY, tenant_id text NOT NULL REFERENCES tenants(id), number text NOT NULL, customer_id text NOT NULL, product_id text NOT NULL, quantity numeric(20,6) NOT NULL CHECK(quantity>0), unit_price numeric(20,6) NOT NULL CHECK(unit_price>=0), delivered numeric(20,6) NOT NULL DEFAULT 0 CHECK(delivered>=0 AND delivered<=quantity), due_date date NOT NULL, status text NOT NULL DEFAULT 'CONFIRMED' CHECK(status IN ('CONFIRMED','PARTIAL','DELIVERED')), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,id), UNIQUE(tenant_id,number), FOREIGN KEY(tenant_id,customer_id) REFERENCES partners(tenant_id,id), FOREIGN KEY(tenant_id,product_id) REFERENCES items(tenant_id,id));
CREATE TABLE purchase_orders (id text PRIMARY KEY, tenant_id text NOT NULL REFERENCES tenants(id), number text NOT NULL, supplier_id text NOT NULL, item_id text NOT NULL, quantity numeric(20,6) NOT NULL CHECK(quantity>0), unit_cost numeric(20,6) NOT NULL CHECK(unit_cost>=0), received numeric(20,6) NOT NULL DEFAULT 0 CHECK(received>=0 AND received<=quantity), due_date date NOT NULL, status text NOT NULL DEFAULT 'DRAFT' CHECK(status IN ('DRAFT','APPROVED','PARTIAL','RECEIVED')), created_by text NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,id), UNIQUE(tenant_id,number), FOREIGN KEY(tenant_id,supplier_id) REFERENCES partners(tenant_id,id), FOREIGN KEY(tenant_id,item_id) REFERENCES items(tenant_id,id));
CREATE TABLE manufacturing_orders (id text PRIMARY KEY, tenant_id text NOT NULL REFERENCES tenants(id), number text NOT NULL, product_id text NOT NULL, bom_id text NOT NULL, bom_revision text NOT NULL, sales_order_id text, machine_id text NOT NULL, factory_id text NOT NULL, quantity numeric(20,6) NOT NULL CHECK(quantity>0), good_qty numeric(20,6) NOT NULL DEFAULT 0 CHECK(good_qty>=0), scrap_qty numeric(20,6) NOT NULL DEFAULT 0 CHECK(scrap_qty>=0), status text NOT NULL DEFAULT 'DRAFT' CHECK(status IN ('DRAFT','APPROVED','MATERIALS_RESERVED','RELEASED','IN_PROGRESS','ON_HOLD','PARTIALLY_COMPLETED','QUALITY_REVIEW','COMPLETED','CLOSED','CANCELLED')), priority text NOT NULL CHECK(priority IN ('NORMAL','HIGH','URGENT')), due_date date NOT NULL, estimated_cost numeric(20,6) NOT NULL DEFAULT 0, material_cost numeric(20,6) NOT NULL DEFAULT 0, conversion_cost numeric(20,6) NOT NULL DEFAULT 0, wip_cost numeric(20,6) NOT NULL DEFAULT 0 CHECK(wip_cost>=0), finished_cost numeric(20,6) NOT NULL DEFAULT 0, scrap_cost numeric(20,6) NOT NULL DEFAULT 0, created_by text NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), started_at timestamptz, CHECK(good_qty+scrap_qty<=quantity), UNIQUE(tenant_id,id), UNIQUE(tenant_id,number), FOREIGN KEY(tenant_id,product_id) REFERENCES items(tenant_id,id), FOREIGN KEY(tenant_id,bom_id) REFERENCES boms(tenant_id,id), FOREIGN KEY(tenant_id,sales_order_id) REFERENCES sales_orders(tenant_id,id), FOREIGN KEY(tenant_id,machine_id) REFERENCES machines(tenant_id,id), FOREIGN KEY(tenant_id,factory_id) REFERENCES factories(tenant_id,id));
CREATE TABLE order_materials (id text PRIMARY KEY, tenant_id text NOT NULL REFERENCES tenants(id), order_id text NOT NULL, item_id text NOT NULL, required_qty numeric(20,6) NOT NULL CHECK(required_qty>0), issued_qty numeric(20,6) NOT NULL DEFAULT 0, UNIQUE(tenant_id,order_id,item_id), FOREIGN KEY(tenant_id,order_id) REFERENCES manufacturing_orders(tenant_id,id), FOREIGN KEY(tenant_id,item_id) REFERENCES items(tenant_id,id));
CREATE TABLE lots (id text PRIMARY KEY, tenant_id text NOT NULL REFERENCES tenants(id), number text NOT NULL, item_id text NOT NULL, warehouse_id text NOT NULL, status text NOT NULL CHECK(status IN ('QUARANTINE','RELEASED','REJECTED')), source_type text NOT NULL, source_id text NOT NULL, unit_cost numeric(20,6) NOT NULL CHECK(unit_cost>=0), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,id), UNIQUE(tenant_id,number), FOREIGN KEY(tenant_id,item_id) REFERENCES items(tenant_id,id), FOREIGN KEY(tenant_id,warehouse_id) REFERENCES warehouses(tenant_id,id));
CREATE TABLE stock_balances (tenant_id text NOT NULL, lot_id text NOT NULL, quantity numeric(20,6) NOT NULL DEFAULT 0 CHECK(quantity>=0), reserved numeric(20,6) NOT NULL DEFAULT 0 CHECK(reserved>=0 AND reserved<=quantity), value_amount numeric(20,6) NOT NULL DEFAULT 0 CHECK(value_amount>=0), PRIMARY KEY(tenant_id,lot_id), FOREIGN KEY(tenant_id,lot_id) REFERENCES lots(tenant_id,id));
CREATE TABLE stock_ledger (id text PRIMARY KEY, tenant_id text NOT NULL REFERENCES tenants(id), lot_id text NOT NULL, item_id text NOT NULL, warehouse_id text NOT NULL, uom text NOT NULL, delta numeric(20,6) NOT NULL CHECK(delta<>0), value_delta numeric(20,6) NOT NULL, unit_cost numeric(20,6) NOT NULL CHECK(unit_cost>=0), reference text NOT NULL, reason text NOT NULL, actor text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(tenant_id,lot_id) REFERENCES lots(tenant_id,id), FOREIGN KEY(tenant_id,item_id) REFERENCES items(tenant_id,id), FOREIGN KEY(tenant_id,warehouse_id) REFERENCES warehouses(tenant_id,id));
CREATE TABLE reservations (id text PRIMARY KEY, tenant_id text NOT NULL REFERENCES tenants(id), order_id text NOT NULL, lot_id text NOT NULL, item_id text NOT NULL, quantity numeric(20,6) NOT NULL CHECK(quantity>0), status text NOT NULL CHECK(status IN ('RESERVED','ISSUED','RELEASED')), FOREIGN KEY(tenant_id,order_id) REFERENCES manufacturing_orders(tenant_id,id), FOREIGN KEY(tenant_id,lot_id) REFERENCES lots(tenant_id,id), FOREIGN KEY(tenant_id,item_id) REFERENCES items(tenant_id,id));
CREATE TABLE inspections (id text PRIMARY KEY, tenant_id text NOT NULL REFERENCES tenants(id), lot_id text NOT NULL, type text NOT NULL, status text NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','PASSED','FAILED')), notes text NOT NULL DEFAULT '', inspected_by text, inspected_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,id), FOREIGN KEY(tenant_id,lot_id) REFERENCES lots(tenant_id,id));
CREATE TABLE receipts (id text PRIMARY KEY, tenant_id text NOT NULL REFERENCES tenants(id), purchase_order_id text NOT NULL, lot_id text NOT NULL, quantity numeric(20,6) NOT NULL CHECK(quantity>0), invoice_reference text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,id), FOREIGN KEY(tenant_id,purchase_order_id) REFERENCES purchase_orders(tenant_id,id), FOREIGN KEY(tenant_id,lot_id) REFERENCES lots(tenant_id,id));
CREATE TABLE production_actuals (id text PRIMARY KEY, tenant_id text NOT NULL REFERENCES tenants(id), order_id text NOT NULL, lot_id text, good_qty numeric(20,6) NOT NULL, scrap_qty numeric(20,6) NOT NULL, labour_cost numeric(20,6) NOT NULL, machine_cost numeric(20,6) NOT NULL, notes text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(tenant_id,order_id) REFERENCES manufacturing_orders(tenant_id,id), FOREIGN KEY(tenant_id,lot_id) REFERENCES lots(tenant_id,id));
CREATE TABLE deliveries (id text PRIMARY KEY, tenant_id text NOT NULL REFERENCES tenants(id), sales_order_id text NOT NULL, lot_id text NOT NULL, quantity numeric(20,6) NOT NULL CHECK(quantity>0), reference text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(tenant_id,sales_order_id) REFERENCES sales_orders(tenant_id,id), FOREIGN KEY(tenant_id,lot_id) REFERENCES lots(tenant_id,id));
CREATE TABLE journal_entries (id text PRIMARY KEY, tenant_id text NOT NULL REFERENCES tenants(id), reference text NOT NULL, description text NOT NULL, actor text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,id));
CREATE TABLE journal_lines (id text PRIMARY KEY, tenant_id text NOT NULL REFERENCES tenants(id), entry_id text NOT NULL, account text NOT NULL, debit numeric(20,6) NOT NULL DEFAULT 0 CHECK(debit>=0), credit numeric(20,6) NOT NULL DEFAULT 0 CHECK(credit>=0), CHECK((debit=0)<>(credit=0)), FOREIGN KEY(tenant_id,entry_id) REFERENCES journal_entries(tenant_id,id));
CREATE TABLE audit_events (id text PRIMARY KEY, tenant_id text NOT NULL REFERENCES tenants(id), actor text NOT NULL, action text NOT NULL, reference text NOT NULL, detail text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE outbox_events (id text PRIMARY KEY, tenant_id text NOT NULL REFERENCES tenants(id), event_type text NOT NULL, reference text NOT NULL, payload jsonb NOT NULL, status text NOT NULL DEFAULT 'LOCAL_ONLY', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE idempotency_keys (tenant_id text NOT NULL REFERENCES tenants(id), request_key text NOT NULL, action text NOT NULL, payload_hash text NOT NULL, response jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(tenant_id,request_key));
CREATE TABLE financial_periods (tenant_id text NOT NULL REFERENCES tenants(id), end_date date NOT NULL, closed boolean NOT NULL DEFAULT false, PRIMARY KEY(tenant_id,end_date));

CREATE INDEX stock_ledger_tenant_created ON stock_ledger(tenant_id,created_at DESC);
CREATE INDEX mo_tenant_status ON manufacturing_orders(tenant_id,status,due_date);
CREATE INDEX lots_tenant_item_status ON lots(tenant_id,item_id,status,created_at);
CREATE INDEX reservations_tenant_order ON reservations(tenant_id,order_id,status);
CREATE INDEX audit_tenant_created ON audit_events(tenant_id,created_at DESC);
CREATE INDEX inspections_tenant_status ON inspections(tenant_id,status);
CREATE INDEX outbox_tenant_status ON outbox_events(tenant_id,status,created_at);

CREATE FUNCTION reject_history_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Posted history is immutable; use a compensating transaction'; END; $$;
CREATE TRIGGER stock_history_immutable BEFORE UPDATE OR DELETE ON stock_ledger FOR EACH ROW EXECUTE FUNCTION reject_history_mutation();
CREATE TRIGGER journal_history_immutable BEFORE UPDATE OR DELETE ON journal_entries FOR EACH ROW EXECUTE FUNCTION reject_history_mutation();
CREATE TRIGGER journal_lines_immutable BEFORE UPDATE OR DELETE ON journal_lines FOR EACH ROW EXECUTE FUNCTION reject_history_mutation();
CREATE TRIGGER audit_immutable BEFORE UPDATE OR DELETE ON audit_events FOR EACH ROW EXECUTE FUNCTION reject_history_mutation();

CREATE FUNCTION apply_stock_entry() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE actual_item text; actual_warehouse text; actual_uom text;
BEGIN
  SELECT l.item_id,l.warehouse_id,i.uom INTO actual_item,actual_warehouse,actual_uom FROM lots l JOIN items i ON i.tenant_id=l.tenant_id AND i.id=l.item_id WHERE l.tenant_id=NEW.tenant_id AND l.id=NEW.lot_id FOR UPDATE OF l;
  IF NEW.item_id<>actual_item OR NEW.warehouse_id<>actual_warehouse OR NEW.uom<>actual_uom THEN RAISE EXCEPTION 'Ledger unit, item or warehouse mismatch'; END IF;
  INSERT INTO stock_balances(tenant_id,lot_id,quantity) VALUES(NEW.tenant_id,NEW.lot_id,0) ON CONFLICT DO NOTHING;
  IF NEW.delta*NEW.value_delta<0 THEN RAISE EXCEPTION 'Ledger quantity and value signs must agree'; END IF;
  UPDATE stock_balances SET quantity=quantity+NEW.delta,value_amount=value_amount+NEW.value_delta WHERE tenant_id=NEW.tenant_id AND lot_id=NEW.lot_id;
  RETURN NEW;
END; $$;
CREATE TRIGGER apply_stock_balance AFTER INSERT ON stock_ledger FOR EACH ROW EXECUTE FUNCTION apply_stock_entry();

CREATE FUNCTION validate_journal_balance() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF EXISTS(SELECT 1 FROM journal_lines WHERE tenant_id=NEW.tenant_id AND entry_id=NEW.entry_id GROUP BY entry_id HAVING SUM(debit)<>SUM(credit)) THEN RAISE EXCEPTION 'Journal entry must balance'; END IF;
  RETURN NULL;
END; $$;
CREATE CONSTRAINT TRIGGER journal_must_balance AFTER INSERT ON journal_lines DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION validate_journal_balance();
